INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1f2cb3fa-6045-5f54-a025-50211c596388','TEXT','Proofreading passage PD','The students checked the abbate before the activity began. Our group recorded the abbatiello in the class notebook. The students checked the abbenhaus before the activity began. Our group recorded the abbett in the class notebook. The students checked the abbeville before the activity began. Our group recorded the abbey in the class notebook. The students checked the abbie before the activity began. Our group recorded the abbitt in the class notebook. The students checked the abbot before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
